stepxmp.pre:
h1 {
    string-set: chapter-title content(text), chapter-label "Chapter " counter(chapter);
}

group {
    counter-reset: item;
}

item {
    counter-increment: item;
}

item::before {
    content: counter(item) " (" counters(item, ".") ") ";
}

title {
    string-set: title-text content(text), title-prefix content(before), title-code attr(code, "No code");
}

title::before {
    content: "Chapter ";
}

@page {
    @top-left {
        content: string(title-prefix) string(title-code);
    }
    @top-right {
        content: string(title-text);
    }
}
